<?php
require_once __DIR__.'/../includes/functions.php';require_role(['super_admin']);verify_csrf();$db=db();$error='';
$keys=['clinic_name'=>'Clinic name','clinic_email'=>'Clinic email','clinic_phone'=>'Clinic phone','clinic_address'=>'Clinic address','currency_symbol'=>'Currency symbol','tax_rate_percent'=>'Tax rate (%)','appointment_slot_minutes'=>'Default appointment slot (minutes)'];
if($_SERVER['REQUEST_METHOD']==='POST'){try{$db->beginTransaction();foreach($keys as $key=>$label){$val=post_string($key,1000);if($key==='clinic_email'&&$val!==''&&!filter_var($val,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid clinic email.');if($key==='tax_rate_percent'&&(!is_numeric($val)||(float)$val<0||(float)$val>100))throw new RuntimeException('Tax rate must be between 0 and 100.');if($key==='appointment_slot_minutes'&&(!ctype_digit($val)||(int)$val<5||(int)$val>240))throw new RuntimeException('Slot duration must be between 5 and 240 minutes.');$s=$db->prepare('INSERT INTO settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)');$s->execute([$key,$val,current_user()['id']]);}$db->commit();audit(current_user()['id'],'SETTINGS_UPDATED','settings',null,'Clinic configuration updated');flash('success','Settings saved.');redirect('settings/index.php');}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error=$ex->getMessage();}}
$pageTitle='Settings';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/page.php';page_heading('Configuration','Clinic settings','Update the clinic identity and basic scheduling preferences.');?>
<?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card"><div class="card-body"><form method="post"><?=csrf_field()?><div class="row g-3"><?php foreach($keys as $key=>$label):?><div class="col-md-6"><label class="form-label"><?=e($label)?></label><?php if($key==='clinic_address'):?><textarea class="form-control" name="<?=$key?>" rows="2"><?=e(setting($key))?></textarea><?php else:?><input class="form-control" name="<?=$key?>" value="<?=e(setting($key, $key==='currency_symbol'?'$':($key==='tax_rate_percent'?'0':($key==='appointment_slot_minutes'?'30':''))))?>" required><?php endif;?></div><?php endforeach;?></div><button class="btn btn-primary mt-4">Save settings</button></form></div></div><?php require __DIR__.'/../includes/footer.php';?>